      appendedSkeletons.forEach(function (node) { node.remove(); });
      var items = data.items || [];
      if (reset) { browse.items = []; grid.innerHTML = ""; }
      browse.items = browse.items.concat(items); browse.cursor = data.next_cursor || null; browse.exhausted = !browse.cursor; browse.facets = data.facets || browse.facets;
      if (items.length) { var fragment = document.createElement("div"); fragment.innerHTML = cardsHtml(items, 2); while (fragment.firstChild) grid.appendChild(fragment.firstChild); wirePreviewCards(grid); }
      if (!browse.items.length) grid.innerHTML = emptyState("No models match", "Clear a filter or try a broader search.", '<button class="btn ghost" type="button" data-clear-results>Clear filters</button>');
